={{ (() => {
  const trigger = ($('GitHub Discussion Events').isExecuted
    ? $('GitHub Discussion Events')
    : $('GitHub Webhook (Direct URL)')).item.json;
  const disc = trigger.body.discussion;
  const repo = trigger.body.repository;
  const issueNode = $('Create Repository Issue').isExecuted ? $('Create Repository Issue').item.json : $('Set Existing Issue Data').item.json;
  const issueNum = issueNode.number;
  const discBody = disc.body || '';
  const author = disc.user.login;
  const resolveResult = $('Call Resolve Issue API').item.json;

  // Extract media URLs
  const allUrls = discBody.match(/https?:\/\/[^\s)\\"<>]+/g) || [];
  const mediaUrls = allUrls.filter(u =>
    /user-attachments|githubusercontent|\.(png|jpe?g|gif|webp|svg|mp4|mov|webm)(\?|$)/i.test(u)
  );

  // Extract log code blocks
  const codeBlocks = [];
  const codeRe = /```([\w-]*)\r?\n([\s\S]*?)```/g;
  let m;
  while ((m = codeRe.exec(discBody)) !== null) {
    const lang = m[1].trim();
    const code = m[2].trim();
    if (!lang || /^(text|log|sh|bash|shell|json|yaml|yml|txt)$/i.test(lang)
        || /error|exception|traceback|stack|fatal|warn|429|quota/i.test(code)) {
      codeBlocks.push({ lang: lang || 'text', code });
    }
  }

  let body = '## \u{1F916} Automated Fix Ã¢ÂÂ Turing-agent (powered by TinyFish)\n\n';
  body += `> This PR was **automatically generated, coded, and verified** by [Turing-agent](https://github.com/Turing-agent) `;
  body += `to resolve Discussion [#${disc.number}](${disc.html_url}).\n\n`;
  body += `**Closes** #${issueNum}  \n`;
  body += `**Discussion**: [#${disc.number} Ã¢ÂÂ ${disc.title}](${disc.html_url})  \n`;
  body += `**Branch**: \`${resolveResult.branch_name || ('issue-' + issueNum)}\`  \n\n`;

  // TinyFish live verification if available
  if (resolveResult.tinyfish_summary || (resolveResult.tinyfish_screenshots && resolveResult.tinyfish_screenshots.length > 0)) {
    body += '---\n\n## Ã°ÂÂÂ TinyFish Web Agent Live Verification\n\n';
    if (resolveResult.live_url) {
      body += `**Target Website**: ${resolveResult.live_url}\n\n`;
    }
    if (resolveResult.tinyfish_summary) {
      body += `> ${resolveResult.tinyfish_summary}\n\n`;
    }
    (resolveResult.tinyfish_screenshots || []).forEach((img, i) => {
      body += `**Screenshot ${i+1}**: [View Live Screenshot](${img})\n\n![TinyFish Verification Step ${i+1}](${img})\n\n`;
    });
  }

  // AI fix summary
  const filesChanged = resolveResult.files_changed || (resolveResult.changed_paths || []).length;
  if (filesChanged > 0) {
    body += '---\n\n## \u{1F9E0} AI-Generated Fix\n\n';
    if (resolveResult.summary) {
      body += `> ${resolveResult.summary}\n\n`;
    }
    body += `**Files changed (${filesChanged}):**\n\n`;
    (resolveResult.changed_paths || []).forEach(p => { body += `- \`${p}\`\n`; });
    body += '\n';
  }

  body += '---\n\n## \u{1F4CB} Problem Description\n\n';
  const descPreview = discBody.length > 2000
    ? discBody.substring(0, 2000) + '\n\n_...full details in the linked discussion_'
    : discBody;
  body += descPreview + '\n\n';

  if (mediaUrls.length > 0) {
    body += '---\n\n## \u{1F3A8} Visual Evidence\n\n';
    mediaUrls.forEach((url, i) => {
      const isVideo = /\.(mp4|mov|webm)(\?|$)/i.test(url);
      if (isVideo) {
        body += `**\u{1F3AC} Recording ${i+1}:** [View video](${url})\n\n`;
      } else {
        body += `**\u{1F4F8} Screenshot ${i+1}:**\n\n![Visual evidence from discussion #${disc.number}](${url})\n\n`;
      }
    });
  }

  if (codeBlocks.length > 0) {
    body += '---\n\n## \u{1F4C4} Relevant Logs & Errors\n\n';
    codeBlocks.slice(0, 4).forEach((block, i) => {
      const code = block.code.length > 1000 ? block.code.substring(0, 1000) + '\n# ...(truncated)' : block.code;
      body += `<details>\n<summary>Log block ${i+1}</summary>\n\n\`\`\`${block.lang}\n${code}\n\`\`\`\n\n</details>\n\n`;
    });
  }

  body += '---\n\n## \u{1F517} References\n\n';
  body += `- \u{1F4CC} **Discussion**: [#${disc.number} Ã¢ÂÂ ${disc.title}](${disc.html_url})\n`;
  body += `- \u{1F517} **Issue**: #${issueNum} Ã¢ÂÂ ${issueNode.html_url}\n`;
  body += `- \u{1F464} **Discussion Author / Co-author**: @${author}\n`;
  body += `- \u{1F3E0} **Repository**: [${repo.full_name}](${repo.html_url})\n\n`;
  body += '---\n\n';
  body += `_This PR contains AI-generated code changes by [Turing-agent](https://github.com/Turing-agent) powered by [TinyFish](https://tinyfish.ai). Please review carefully before merging._\n\n`;
  body += `Co-authored-by: ${author} <${author}@users.noreply.github.com>`;

  return JSON.stringify({
    title: 'Fix #' + issueNum + ': ' + issueNode.title,
    head: resolveResult.branch_name || ('issue-' + issueNum),
    base: repo.default_branch,
    body: body
  });
})() }}

={{ (() => {
  const trigger = ($('GitHub Discussion Events').isExecuted ? $('GitHub Discussion Events') : $('GitHub Webhook (Direct URL)')).item.json;
  const issue = $('Create Repository Issue').isExecuted ? $('Create Repository Issue').item.json : $('Set Existing Issue Data').item.json;
  const progressComment = $('Post Initial Progress Comment').isExecuted ? $('Post Initial Progress Comment').item.json : $('Post Approved Already Raised Comment').item.json;
  const commentId = progressComment && progressComment.data && progressComment.data.addDiscussionComment && progressComment.data.addDiscussionComment.comment ? progressComment.data.addDiscussionComment.comment.id : null;
  const filesToModify = $('Consolidate Discussion Issue').isExecuted ? ($('Consolidate Discussion Issue').item.json.files_to_modify || []) : [];
  return JSON.stringify({
    issue_title: issue.title,
    issue_body: issue.body,
    issue_number: issue.number,
    repo_full_name: trigger.body.repository.full_name,
    base_tree_sha: $('Get Base Commit').item.json.tree.sha,
    base_commit_sha: $('Get Base Commit').item.json.sha,
    discussion_url: trigger.body.discussion.html_url,
    author: trigger.body.discussion.user.login,
    issue_url: issue.html_url,
    progress_comment_id: commentId,
    files_to_modify: filesToModify
  });
})() }}

={{ (() => {
  const pr = $json;
  const resolve = $('Call Resolve Issue API').item.json;
  const issue = $('Create Repository Issue').isExecuted ? $('Create Repository Issue').item.json : $('Set Existing Issue Data').item.json;
  const trigger = ($('GitHub Discussion Events').isExecuted ? $('GitHub Discussion Events') : $('GitHub Webhook (Direct URL)')).item.json;
  const author = trigger.body.discussion.user.login;
  const progressNode = $('Post Initial Progress Comment').isExecuted ? $('Post Initial Progress Comment').item.json : $('Post Approved Already Raised Comment').item.json;
  const commentId = progressNode && progressNode.data && progressNode.data.addDiscussionComment && progressNode.data.addDiscussionComment.comment ? progressNode.data.addDiscussionComment.comment.id : null;

  let body = "<!-- turing-bot-progress -->\n### Ã¢ÂÂ Turing-agent Fix Completed!\n";
  body += "- [x] Maintainer approval verified (@" + author + ")\n";
  body += "- [x] Created & linked Issue [#" + issue.number + "](" + issue.html_url + ")\n";
  body += "- [x] Codebase files inspected (" + (resolve.files_analyzed || 0) + " files analyzed)\n";
  body += "- [x] Solution synthesized by Groq AI (" + (resolve.files_changed || 0) + " file(s) modified)\n";
  body += "- [x] Changes committed & pushed to branch `" + resolve.branch_name + "` (`" + (resolve.commit_sha ? resolve.commit_sha.substring(0, 7) : '') + "`)\n";
  body += "- [x] **Pull Request Opened**: [#" + pr.number + "](" + pr.html_url + ") Ã°ÂÂÂ\n\n";

  if (resolve.changed_paths && resolve.changed_paths.length > 0) {
    body += "**Modified Files:**\n";
    resolve.changed_paths.forEach(p => { body += "- `" + p + "`\n"; });
    body += "\n";
  }

  if (resolve.summary) {
    body += "> **Summary**: " + resolve.summary + "\n\n";
  }

  body += "_Co-authored with @" + author + "._";

  return JSON.stringify({
    query: "mutation($input: UpdateDiscussionCommentInput!) { updateDiscussionComment(input: $input) { comment { id url } } }",
    variables: {
      input: {
        commentId: commentId,
        body: body
      }
    }
  });
})() }}

